// Some portions generated by Claude
export type Bounds = { minX: number; minY: number; maxX: number; maxY: number };

/** Dynamic rectangle broad phase; exact narrow-phase scores stay with callers. */
export class SpatialGrid {
  private entries: Bounds[] = [];
  private columns = new Map<number, Map<number, number[]>>();
  private oversized: number[] = [];
  private seen = new Uint32Array(64);
  private epoch = 0;
  private cellSize: number;

  constructor(cellSize = 128) {
    if (!Number.isFinite(cellSize) || cellSize <= 0) throw new RangeError("Invalid cell size");
    this.cellSize = cellSize;
  }

  insert(bounds: Bounds) {
    if (!Object.values(bounds).every(Number.isFinite) || bounds.minX > bounds.maxX || bounds.minY > bounds.maxY) {
      throw new RangeError("Invalid spatial bounds");
    }
    const id = this.entries.length;
    this.entries.push(bounds);
    if (id >= this.seen.length) {
      const grown = new Uint32Array(this.seen.length * 2);
      grown.set(this.seen);
      this.seen = grown;
    }
    this.index(id, bounds);
    return id;
  }

  /** Preserve the entry ID and remove old memberships before inserting anew. */
  update(id: number, bounds: Bounds) {
    if (!Number.isInteger(id) || id < 0 || id >= this.entries.length ||
        !Object.values(bounds).every(Number.isFinite) || bounds.minX > bounds.maxX || bounds.minY > bounds.maxY) {
      throw new RangeError('Invalid spatial update');
    }
    const old = this.entries[id];
    const x0 = Math.floor(old.minX / this.cellSize), x1 = Math.floor(old.maxX / this.cellSize);
    const y0 = Math.floor(old.minY / this.cellSize), y1 = Math.floor(old.maxY / this.cellSize);
    if ((x1 - x0 + 1) * (y1 - y0 + 1) > 64 || ![x0, x1, y0, y1].every(Number.isSafeInteger)) {
      const at = this.oversized.indexOf(id); if (at >= 0) this.oversized.splice(at, 1);
    } else for (let x = x0; x <= x1; x++) {
      const column = this.columns.get(x); if (!column) continue;
      for (let y = y0; y <= y1; y++) {
        const cell = column.get(y); if (!cell) continue;
        const at = cell.indexOf(id); if (at >= 0) cell.splice(at, 1);
        if (!cell.length) column.delete(y);
      }
      if (!column.size) this.columns.delete(x);
    }
    this.entries[id] = bounds;
    this.index(id, bounds);
  }

  private index(id: number, bounds: Bounds) {
    const x0 = Math.floor(bounds.minX / this.cellSize), x1 = Math.floor(bounds.maxX / this.cellSize);
    const y0 = Math.floor(bounds.minY / this.cellSize), y1 = Math.floor(bounds.maxY / this.cellSize);
    if ((x1 - x0 + 1) * (y1 - y0 + 1) > 64 ||
        ![x0, x1, y0, y1].every(Number.isSafeInteger)) {
      this.oversized.push(id);
      return;
    }
    for (let x = x0; x <= x1; x++) {
      let column = this.columns.get(x);
      if (!column) this.columns.set(x, column = new Map());
      for (let y = y0; y <= y1; y++) {
        let cell = column.get(y);
        if (!cell) column.set(y, cell = []);
        cell.push(id);
      }
    }
  }

  search(minX: number, minY: number, maxX: number, maxY: number, result: number[] = []) {
    result.length = 0;
    if (![minX, minY, maxX, maxY].every(Number.isFinite) || minX > maxX || minY > maxY) return result;
    this.epoch = (this.epoch + 1) >>> 0;
    if (this.epoch === 0) { this.seen.fill(0); this.epoch = 1; }
    const visit = (id: number) => {
      if (this.seen[id] === this.epoch) return;
      this.seen[id] = this.epoch;
      const b = this.entries[id];
      if (b.maxX >= minX && b.minX <= maxX && b.maxY >= minY && b.minY <= maxY) result.push(id);
    };
    const x0 = Math.floor(minX / this.cellSize), x1 = Math.floor(maxX / this.cellSize);
    const y0 = Math.floor(minY / this.cellSize), y1 = Math.floor(maxY / this.cellSize);
    if ((x1 - x0 + 1) * (y1 - y0 + 1) > this.entries.length * 2 ||
        ![x0, x1, y0, y1].every(Number.isSafeInteger)) {
      for (let id = 0; id < this.entries.length; id++) visit(id);
    } else {
      for (let x = x0; x <= x1; x++) {
        const column = this.columns.get(x);
        if (!column) continue;
        for (let y = y0; y <= y1; y++) {
          const cell = column.get(y);
          if (cell) for (const id of cell) visit(id);
        }
      }
      for (const id of this.oversized) visit(id);
    }
    // Stable order preserves floating-point accumulation and tie breaking.
    result.sort((a, b) => a - b);
    return result;
  }
}
